package com.codenzic.workspace.leave.domain; import jakarta.persistence.*; import lombok.*; import java.time.*; import java.util.UUID;
@Entity @Table(name="leave_requests") @Getter @NoArgsConstructor public class LeaveRequest { @Id @GeneratedValue(strategy=GenerationType.UUID) UUID id; @Column(nullable=false) UUID organizationId; @Column(nullable=false) UUID employeeId; @Column(nullable=false,length=30) String leaveType; @Column(nullable=false) LocalDate startDate; @Column(nullable=false) LocalDate endDate; @Column(length=1000) String reason; @Column(nullable=false,length=20) String status="PENDING"; UUID reviewedBy; Instant reviewedAt; @Column(length=1000) String reviewComment; public LeaveRequest(UUID o,UUID e,String type,LocalDate start,LocalDate end,String reason){organizationId=o;employeeId=e;leaveType=type;startDate=start;endDate=end;this.reason=reason;} public void update(LocalDate start,LocalDate end,String reason){if(!status.equals("PENDING"))throw new IllegalStateException("Only pending leave can be updated");startDate=start;endDate=end;this.reason=reason;} public void changeLeaveType(String type){if(!status.equals("PENDING"))throw new IllegalStateException("Only pending leave can be updated");leaveType=type;} public void transition(String next,UUID reviewer,String comment){if(!status.equals("PENDING")) throw new IllegalStateException("Only pending leave can be reviewed"); status=next;reviewedBy=reviewer;reviewedAt=Instant.now();reviewComment=comment;}}
